import {Icon, IndexPath} from '@ui-kitten/components';
import React, {useState} from 'react';
import {TouchableOpacity, View} from 'react-native';
import DropdownListCM from '../../../../components/DropDownList';
import {useTranslation} from 'react-i18next';
import {Font} from '../../../../../constants';
import TextCM from '../../../../components/Text';
import InputDate from './InputDate';
import {listPayment, listRequestStatus, listStatusReceipt} from './helper';
import {
  useReceiptZustandStore,
  ValueFilterSearch,
} from '../../store/myReceiptZustandStore';
import Toast from 'react-native-toast-message';
type Props = {
  onClose: () => void;
  handleSubmitFilter?: () => void;
  setValueFilterSearch: React.Dispatch<
    React.SetStateAction<ValueFilterSearch | undefined>
  >;
  valueFilterSearch?: ValueFilterSearch;
};
const ModalFilter = ({
  handleSubmitFilter,
  setValueFilterSearch,
  valueFilterSearch,
}: Props) => {
  const {t} = useTranslation();
  const {listTypeReceipt} = useReceiptZustandStore();
  const [valueFilterSearchState, setValueFilterSearchState] = useState<
    ValueFilterSearch | undefined
  >(valueFilterSearch);

  const onChangeStartDate = (value: string | null) => {
    const newStart = value ? new Date(value) : undefined;
    const {endDate} = valueFilterSearch?.rangeDay ?? {};
    if (endDate && newStart && newStart > endDate) {
      Toast.show({
        type: 'error',
        text1: t('CM.noti'),
        text2: t('BLDT.start_date_not_greater_than_end_date'),
      });
      return;
    }

    setValueFilterSearchState({
      ...valueFilterSearchState,
      rangeDay: {
        ...valueFilterSearchState?.rangeDay,
        startDate: newStart,
      },
    });
  };
  const onChangeEndDate = (value: string | null) => {
    // const today = new Date();
    // today.setHours(0, 0, 0, 0);
    const newEnd = value ? new Date(value) : undefined;
    // if (newEnd && newEnd > today) {
    //   Toast.show({
    //     type: 'error',
    //     text1: t('CM.noti'),
    //     text2: 'Ngày kết thúc không được lớn hơn ngày hôm nay.',
    //   });
    //   return;
    // }
    const {startDate} = valueFilterSearchState?.rangeDay ?? {};
    if (startDate && newEnd && newEnd < startDate) {
      Toast.show({
        type: 'error',
        text1: t('CM.not'),
        text2: t('BLDT.end_date_not_less_than_start_date'),
      });
      return;
    }
    setValueFilterSearchState({
      ...valueFilterSearchState,
      rangeDay: {...valueFilterSearchState?.rangeDay, endDate: newEnd},
    });
  };

  const handleClear = () => {
    setValueFilterSearchState(undefined);
  };

  const handleSubmit = () => {
    setValueFilterSearch(valueFilterSearchState);
    handleSubmitFilter?.();
  };

  return (
    <View style={{backgroundColor: '#fff'}}>
      <View style={{marginVertical: 4}}>
        <TextCM
          style={{
            marginVertical: 8,
            fontFamily: Font.InterMedium500,
            fontSize: 14,
          }}>
          {t('BLDT.type_receipt')}
        </TextCM>
        <DropdownListCM
          onSelect={(item: IndexPath[]) => {
            setValueFilterSearchState({...valueFilterSearchState, type: item});
          }}
          valueSelect={valueFilterSearchState?.type}
          placeholder={t('BLDT.choose_type_receipt')}
          multiple={true}
          listData={listTypeReceipt}
        />
      </View>
      <View style={{marginVertical: 4}}>
        <TextCM
          style={{
            marginVertical: 8,
            fontFamily: Font.InterMedium500,
            fontSize: 14,
          }}>
          {t('BLDT.payment_method')}
        </TextCM>
        <DropdownListCM
          onSelect={(item: IndexPath[]) => {
            setValueFilterSearchState({
              ...valueFilterSearchState,
              paymentMethod: item,
            });
          }}
          valueSelect={valueFilterSearchState?.paymentMethod}
          placeholder={t('BLDT.choose_payment_method')}
          multiple={true}
          listData={listPayment}
          isi18n={true}
        />
      </View>
      <View style={{marginVertical: 4}}>
        <TextCM
          style={{
            marginVertical: 8,
            fontFamily: Font.InterMedium500,
            fontSize: 14,
          }}>
          {t('BLDT.receipt_status')}
        </TextCM>
        <DropdownListCM
          onSelect={(item: IndexPath[]) => {
            setValueFilterSearchState({
              ...valueFilterSearchState,
              status: item,
            });
          }}
          valueSelect={valueFilterSearchState?.status}
          placeholder={t('DB.filter.mess1')}
          multiple={true}
          listData={listStatusReceipt}
          isi18n={true}
        />
      </View>

      <View style={{marginVertical: 4}}>
        <TextCM
          style={{
            marginVertical: 8,
            fontFamily: Font.InterMedium500,
            fontSize: 14,
          }}>
          {t('BLDT.funding_status')}
        </TextCM>
        <DropdownListCM
          onSelect={(item: IndexPath[]) => {
            setValueFilterSearchState(prev => ({
              ...prev,
              requestStatus: item,
            }));
          }}
          valueSelect={valueFilterSearchState?.requestStatus}
          placeholder={t('BLDT.choose_funding_status')}
          multiple={true}
          listData={listRequestStatus}
          isi18n={true}
        />
      </View>
      <View style={{marginVertical: 4, marginBottom: 12}}>
        <TextCM
          style={{
            marginVertical: 8,
            fontFamily: Font.InterMedium500,
            fontSize: 14,
          }}>
          {t('HM.createDate')}
        </TextCM>
        <View
          style={{
            flexDirection: 'row',
            justifyContent: 'space-between',
            alignItems: 'center',
            marginTop: 10,
            columnGap: 8,
          }}>
          <InputDate
            containerStyle={{flex: 1}}
            value={valueFilterSearchState?.rangeDay?.startDate || null}
            onChangeDate={value => {
              onChangeStartDate(value);
            }}
            maxDate={new Date()}
            disabled={false}
          />
          <Icon name="arrow-forward-outline" width={20} height={20} />
          <InputDate
            containerStyle={{flex: 1}}
            value={valueFilterSearchState?.rangeDay?.endDate || null}
            onChangeDate={value => {
              onChangeEndDate(value);
            }}
            maxDate={new Date()}
            disabled={false}
          />
        </View>
      </View>
      <View
        style={{
          flexDirection: 'row',
          justifyContent: 'space-evenly',
          alignItems: 'center',
          gap: 16,
        }}>
        <TouchableOpacity
          onPress={handleClear}
          style={{
            flex: 1,
            padding: 12,
            backgroundColor: '#FBEFEA',
            borderRadius: 8,
          }}>
          <TextCM style={{color: '#C83A1B', textAlign: 'center'}}>
            {t('DB.filter.set-default')}
          </TextCM>
        </TouchableOpacity>
        <TouchableOpacity
          onPress={handleSubmit}
          style={{
            flex: 1,
            padding: 12,
            backgroundColor: '#C83A1B',
            borderRadius: 8,
          }}>
          <TextCM style={{color: '#fff', textAlign: 'center'}}>
            {t('BLDT.filter')}
          </TextCM>
        </TouchableOpacity>
      </View>
    </View>
  );
};

export default ModalFilter;
